def public_question(q: dict) -> dict:
    """프론트로 내려줄 형태 — 정답 제거."""
    return {
        "id": q["id"], "topic": q["topic"], "stage": q["stage"], "type": q["type"],
        "prompt": q["prompt"], "hint": q["hint"], "options": q["options"], "playable": q["playable"],
    }
